struct Difference {double meanAbsoluteRgb{};unsigned maximumRgb{};double changedFraction{},brightGrowthFraction{};};
Difference DifferenceBetween(const Image& left,const Image& right){Difference result{};if(left.width!=right.width||left.height!=right.height||left.rgba.size()!=right.rgba.size()||left.rgba.empty()){result.maximumRgb=1000;return result;}std::size_t changed{},brightGrowth{},pixels{};std::uint64_t absolute{};for(std::size_t offset=0;offset<left.rgba.size();offset+=4){unsigned pixelDifference{};for(unsigned channel=0;channel<3;++channel)pixelDifference+=unsigned(std::abs(int(left.rgba[offset+channel])-int(right.rgba[offset+channel])));absolute+=pixelDifference;result.maximumRgb=(std::max)(result.maximumRgb,pixelDifference);changed+=pixelDifference!=0;const unsigned leftRgb=left.rgba[offset]+left.rgba[offset+1]+left.rgba[offset+2],rightRgb=right.rgba[offset]+right.rgba[offset+1]+right.rgba[offset+2];brightGrowth+=leftRgb<=690&&rightRgb>690;++pixels;}result.meanAbsoluteRgb=double(absolute)/double(pixels);result.changedFraction=double(changed)/double(pixels);result.brightGrowthFraction=double(brightGrowth)/double(pixels);return result;}
